#!/usr/bin/env python3
from ta_emss import ta_emss
from ta_emss.utilities.shell_utils import execute_sudo_command
import re
import time

SIM_CELL_ID_START = 5


def configure_bts_f1ap_oam(emss1):
    mrbts_id = emss1.get_object_id('MRBTS')
    nrbts_id = emss1.get_object_id('NRBTS')
    configure_mocs_command = []
    cell_id = SIM_CELL_ID_START
    dl_arfcn = emss1.xterm_get("vdus")[0]['DL_ARFCN']
    ul_arfcn = emss1.xterm_get("vdus")[0]['UL_ARFCN']

    time.sleep(30)

    for vdu in emss1.xterm_get("vdus"):
        vdu['DL_ARFCN'] = dl_arfcn
        vdu['UL_ARFCN'] = ul_arfcn
        du_id = vdu['GNB_DU_ID']
        cell_group_list = []
        for cell in vdu['SERVED_CELLS']:
            configure_mocs_command.append({'MOC': 'NRCELL', 'ID': cell_id,
                                           'actEmergencyCall': 'true',
                                           'actVoNR': 'true',
                                           'emergencyCallRestrictions': [{'emergencyCallMrListIgnore': 'true', 'emergencyCallPlmnHoAllowed': 'true'}],
                                           'numOfRadioResReservForEmergency': 10,
                                           'arpPrioEmergencyCall': 1,
                                           'a1MeashoEnabledSA': 'rsrp',
                                           'a1MeashoSsbRsrpSA': [{'a1HysteresishoSsbRsrpSA': 0,
                                                                  'a1ThresholdhoSsbRsrpSA': 60,
                                                                  'a1TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'a2MeashoEnabledSA': 'rsrp',
                                           'a2MeashoSsbRsrpSA': [{'a2HysteresishoSsbRsrpSA': '0',
                                                                  'a2ThresholdhoSsbRsrpSA': '34',
                                                                  'a2TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'cellReselectionPriority': '0',
                                           'cellDepType': vdu['CELL_DEP_TYPE'],
                                           'filterCoeffSsbRsrp': 'fc4',
                                           'filterCoeffSsbRsrq': 'fc4',
                                           'nrSysInfoProfileDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/NRSYSINFO_PROFILE-1',
                                           'trackingAreaDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/TRACKINGAREA-1',
                                           'freqBandIndicatorNR': vdu['FREQUENCY_BAND'],
                                           'lcrId': cell_id,
                                           'physCellId': cell['PCI'],
                                           'allowUnsuppBcOrBcs': ['accept unknown band combinations'],
                                           'chBw': '50MHz',
                                           'drxProfileNrAnr': [{'drxControl': 'any', 'nrDrxDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/NRDRX-3'}],
                                           'rlfPsccTrigThresholdRsrp': '42',
                                           'a1MeashoEnabled': 'none',
                                           'a2MeashoEnabled': 'none',
                                           'cellTechnology': 'FDD',
                                           })
            configure_mocs_command.append({'MOC': 'NRCELL_FDD', 'ID': f'{cell_id}-1',
                                           'chBwDl': '5MHz',
                                           'chBwUl': '5MHz',
                                           'nrarfcnDl': dl_arfcn,
                                           'nrarfcnUl': ul_arfcn
                                           })
            configure_mocs_command.append({'MOC': 'NRCELLGRP', 'ID': cell_id,
                                           'scs': '15 KHz',
                                           'nrCellList': [cell_id]
                                           })
            cell_group_list.append(cell_id)
            cell_id += 1

        configure_mocs_command.append({'MOC': 'NRDU', 'ID': du_id,
                                       'actConnectedModeMobilityCA': 'true',
                                       'actInterNumerologyCa': 'true',
                                       'carrierAggregationSupportList': ['ca_Fr1Tdd_Any_Sa', 'ca_Fr1Tdd_Fdd_Sa', 'ca_Fr1Tdd_Sa'],
                                       'flexibleCAMode': 'ConfigurationIndependent',
                                       'gNbDuId': du_id,
                                       'gNbDuName': f'VDU_{du_id}',
                                       'refNrCellGroup': cell_group_list,
                                       'remoteDuIpAddr': vdu['IP_ADDR']},
                                      )
        dl_arfcn += 20
        ul_arfcn += 20
    emss1.configure_bts(configure_mocs_command, skip_np=False)

    time.sleep(30)
    emss1.configure([
      {'MOC': 'NRCELL', 'ID': 'ALL',
       'actEmergencyCall': 'true',
       'actVoNR': 'true',
       'emergencyCallLimServ': 'true',
       'emergencyCallRestrictions': [{'emergencyCallMrListIgnore': 'true', 'emergencyCallPlmnHoAllowed': 'true'}],
       'numOfRadioResReservForEmergency': 10,
       'arpPrioEmergencyCall': 1,
      },
      {'MOC': 'NRBTS', 'ID': 'ALL',
       'cipherPrefL': [{'nea0': 9, 'nea1_128': 3, 'nea2_128': 4, 'nea3_128': 2}],
       'integrityProtPrefL': [{'nia0': 9, 'nia1_128': 3, 'nia2_128': 4, 'nia3_128': 2}],
      },
      {'MOC': 'NRDU', 'ID': 'ALL',
       'numOfDrbsReservForEmergency': 10,
      },
    ])
    time.sleep(30)


def configure_bts_amf_oam(emss1):
    amf_params = emss1.xterm_get("AMF")
    emss1.configure_bts({'MOC': 'SERVEDAMF', 'ID': amf_params['AMF_SET_ID'],
                         'amfIPAddress': amf_params['AMF_IP_ADDR']},
                        skip_np=False)
    time.sleep(5)


def cleanup_bts_oam(emss1):
    amf_params = emss1.xterm_get("AMF")
    print("Deleting previously added SERVEDAMF MOC")
    emss1.configure_bts({'DEL': 'SERVEDAMF', 'ID': amf_params['AMF_SET_ID']})

    print("Deleting previously added NRDU, NRCELL, NRCELLGRP moc")
    delete_moc_command = []
    number_of_vdus = len(emss1.xterm_get("vdus"))
    number_of_cell_per_vdu = len(emss1.xterm_get("vdus")[0]['SERVED_CELLS'])

    for vdu in emss1.xterm_get("vdus"):
        delete_moc_command.append({'DEL': 'NRDU', 'ID': vdu['GNB_DU_ID']})
    for moc_id in range(SIM_CELL_ID_START, SIM_CELL_ID_START + number_of_vdus * number_of_cell_per_vdu):
        delete_moc_command.append({'DEL': 'NRCELLGRP', 'ID': moc_id})
        delete_moc_command.append({'DEL': 'NRCELL', 'ID': moc_id})
    emss1.configure_bts(delete_moc_command)


if __name__ == "__main__":

    emss1 = ta_emss()
    emss1.setup_emss(user='vcu1', bts_ip='192.168.100.129', oam_ip='192.168.100.1/24', alias='cu1')

    # --- SETUP XTERM PARAMS ---
    print("Setting up...")
    emss1.xterm_setup(
        # --- F1AP PARAMS ---
        bts_f1ap_ip_addr="172.16.1.101",
        vdusim_ip_addr_begin="10.0.1.151",
        vdusim_ip_addr_end="10.0.1.155",
        vdusim_ip_addr_mask=24,
        vdusim_eth_if="eth3",
        init_vdu_gnb_du_id=2,
        init_vdu_frequency_band=85,
        init_vdu_num_cells=3,
        init_vdu_cell_id_begin=SIM_CELL_ID_START,
        init_vdu_ul_arfcn=139800,
        init_vdu_dl_arfcn=145800,
        init_vdu_tac=280,
        init_vdu_mcc="311",
        init_vdu_mnc="489",
        init_vdu_cell_dep_type='SA',
        # --- NGAP PARAMS ---
        amf_ip_addr="10.0.11.27",
        amf_mcc="311",
        amf_mnc="489",
        amf_eth_if="eth3",
        amf_ip_addr_mask="24",
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=True
    )

    # --- CONFIGURE F1AP MOCS ---
    configure_bts_f1ap_oam(emss1)

    # --- CONFIGURE AMF MOCS ---
    configure_bts_amf_oam(emss1)


    # --- START NGAP SIMULATION ---
    print("Starting NGAP...")
    emss1.xterm_start(ngap=True)
    print("Waiting 2 minutes for real DU cells activation...")
    time.sleep(120)

    # --- START F1AP SIMULATION ---
    execute_sudo_command("ip route add 172.16.1.0/24 dev eth3")
    print("Starting F1AP...")
    emss1.xterm_start(f1ap=True)

    # --- WAIT FOR USER INPUT ---
    while True:
        k = input("Enter command (h for help): > ")

        if k == "h":
            print("Add UE: 'a ue_id du_id cell_id'")
            print("Del UE: 'd ue_id'")
            print("Add UE bearer: 'b ue_id'")
            print("Print DUs info: 'p'")
            print("Quit: 'q'")
            continue

        srch_a = re.search(r'a\s+(\d+)\s+(\d+)\s+(\d+)', k)
        srch_d = re.search(r'd\s+(\d+)', k)
        srch_b = re.search(r'b\s+(\d+)', k)

        if srch_a:
            ue_id = srch_a.group(1)
            du_id = srch_a.group(2)
            cell_id = srch_a.group(3)
            emss1.xterm_ue_add(ue_id=ue_id, du_id=du_id, cell_id=cell_id)
        elif srch_d:
            ue_id = srch_d.group(1)
            emss1.xterm_ue_del(ue_id=ue_id)
        elif srch_b:
            ue_id = srch_b.group(1)
            emss1.xterm_ue_add_bearer(ue_id=ue_id)
        elif k == "p":
            for vdu in emss1.xterm_get("vdus"):
                du_id = vdu['GNB_DU_ID']
                print("vDU-{}:".format(du_id))
                for cell_id, cell in enumerate(vdu['SERVED_CELLS'], start=1):
                    print("  cell-{}: {}".format(cell_id, cell))
        elif k == "q":
            break

    # --- DELETE PREVIOUSLY ADDED MOCS ---
#   cleanup_bts_oam(emss1)

    # --- STOP XTERM ---
    print("Stopping xterm")
    emss1.xterm_teardown()
